-- Services remain solely in Lab / Glass. Parts controls only physical parts.
begin;
do $$begin if public.get_parts_flow_version() is distinct from '20261026-parts-flow-1' then raise exception 'Verified Parts Flow is required first.';end if;if to_regprocedure('public.get_parts_services_version()')is not null then if public.get_parts_services_version()is distinct from '20261026-parts-services-separate-1'then raise exception 'Existing services separation needs review.';end if;end if;end;$$;
create table if not exists greenloop_private.parts_services_meta(singleton boolean primary key default true check(singleton),installed_at timestamptz not null default now());
insert into greenloop_private.parts_services_meta(singleton)values(true)on conflict do nothing;
create table if not exists greenloop_private.lab_only_services(job_id uuid not null,cycle integer not null,step_id uuid not null,revision integer not null default 1,names jsonb not null default '[]',saved_at timestamptz not null default now(),saved_by uuid,completed_at timestamptz,primary key(job_id,cycle));
create table if not exists greenloop_private.lab_only_services_audit(id uuid primary key default gen_random_uuid(),job_id uuid not null,cycle integer not null,action text not null,actor uuid,created_at timestamptz not null default now(),previous_names jsonb,names jsonb);
do $$declare t text;begin foreach t in array array['parts_services_meta','lab_only_services','lab_only_services_audit']loop execute format('alter table greenloop_private.%I enable row level security',t);execute format('revoke all on greenloop_private.%I from public,anon,authenticated',t);end loop;end;$$;
-- Copy only pre-update service choices. Replays never replace new Lab edits.
insert into greenloop_private.lab_only_services(job_id,cycle,step_id,names,saved_at,saved_by,completed_at)
select o.job_id,o.cycle,o.step_id,coalesce((select jsonb_agg(x->>'name')from jsonb_array_elements(o.services)x),'[]'),o.submitted_at,o.submitted_by,o.completed_at from greenloop_private.parts_flow_orders o where o.submitted_at<=(select installed_at from greenloop_private.parts_services_meta)on conflict(job_id,cycle)do nothing;
-- Keep the reviewed original implementations private before redirecting old APIs.
do $$declare n text;impl text;ddl text;source_name text;dest text;begin
 foreach n in array array['get_parts_flow_order_v1','submit_lab_parts_plan_v1']loop
 dest:=case n when 'get_parts_flow_order_v1'then 'ps_order_original'else 'ps_submit_original'end;
 if not exists(select 1 from pg_proc where pronamespace='greenloop_private'::regnamespace and proname=dest)then
 select implementation into impl from greenloop_private.office_routines where to_regprocedure(identity)=to_regprocedure(case n when 'get_parts_flow_order_v1'then 'public.get_parts_flow_order_v1(uuid)'else 'public.submit_lab_parts_plan_v1(uuid,integer,jsonb,jsonb)'end);
 if impl is null then raise exception 'Reviewed Parts implementation is missing.';end if;select pg_get_functiondef(to_regprocedure(impl)),proname into ddl,source_name from pg_proc where oid=to_regprocedure(impl);
 ddl:=regexp_replace(ddl,'FUNCTION greenloop_private\.'||source_name||'\(','FUNCTION greenloop_private.'||dest||'(');
 if n='submit_lab_parts_plan_v1'then ddl:=replace(ddl,'Lab / Glass finalised parts and services for Parts','Lab / Glass finalised parts for Parts');end if;execute ddl;
 end if;end loop;
end;$$;
create or replace function greenloop_private.ps_service_state(p_step uuid)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public as $$declare j uuid;d uuid;w uuid;c integer;v_start timestamptz;s greenloop_private.lab_only_services%rowtype;names jsonb;begin
 select wo.job_id,wo.device_id,wo.id into j,d,w from public.job_work_order_steps st join public.job_work_orders wo on wo.id=st.work_order_id join public.jobs job on job.id=wo.job_id and job.deleted_at is null join public.devices dev on dev.id=wo.device_id and dev.deleted_at is null where st.id=p_step and st.department in ('laboratory','glass');if j is null then return null;end if;c:=greenloop_private.pf_cycle(j);select *into s from greenloop_private.lab_only_services where job_id=j and cycle=c;
 if s.job_id is not null then names:=s.names;else
 select max(entered_at)into v_start from greenloop_private.lab_stays_v1(d)where job_id=j;
 select coalesce(jsonb_agg(name order by name),'[]')into names from(select distinct service_name name from public.lab_service_reviews where job_id=j and work_order_step_id=p_step and is_required and reviewed_at>=coalesce(v_start,'-infinity'::timestamptz)
 union select distinct f.check_item from public.initial_qc_findings f join public.job_work_orders wo on wo.initial_qc_inspection_id=f.inspection_id where wo.id=w and c<=1 and public.is_initial_qc_service(f.check_item)and not exists(select 1 from public.lab_service_reviews r where r.work_order_step_id=p_step and r.initial_finding_id=f.id and not r.is_required))q;end if;
 return jsonb_build_object('cycle',c,'services_revision',coalesce(s.revision,0),'services_saved',s.job_id is not null,'services',coalesce((select jsonb_agg(jsonb_build_object('name',x#>>'{}','status',case when s.completed_at is not null then 'completed'when s.job_id is not null then 'saved'else 'planned'end))from jsonb_array_elements(names)x),'[]'));
end;$$;
create or replace function greenloop_private.ps_plan(p_step uuid)returns jsonb language sql stable security definer set search_path=pg_catalog,public as $$select greenloop_private.pf_plan(p_step)||greenloop_private.ps_service_state(p_step);$$;
create or replace function greenloop_private.ps_has_parts(p_order uuid)returns boolean language sql stable security definer set search_path=pg_catalog,public as $$select exists(select 1 from greenloop_private.parts_flow_requests m join public.job_part_requests r on r.id=m.request_id where m.order_id=p_order and(r.status<>'cancelled'or r.quantity_issued>0))or exists(select 1 from greenloop_private.parts_flow_returns where order_id=p_order);$$;
create or replace function greenloop_private.ps_status(p_order uuid)returns text language sql stable security definer set search_path=pg_catalog,public as $$select case when o.completed_at is not null then 'Completed'when exists(select 1 from greenloop_private.parts_flow_returns r where r.order_id=o.id and r.status='pending')then 'Return Requested'when exists(select 1 from public.job_part_requests r join greenloop_private.parts_flow_requests m on m.request_id=r.id where m.order_id=o.id and r.status<>'cancelled'and r.quantity_issued<r.quantity_requested)then case when o.first_issued_at is null then 'Sent to Parts'else 'Partially Issued'end else 'Issued'end from greenloop_private.parts_flow_orders o where o.id=p_order;$$;
create or replace function public.get_lab_parts_plans_v2(p_step_ids uuid[])returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public as $$declare result jsonb;begin perform greenloop_private.pf_cap('lab_glass','view');if p_step_ids is null or cardinality(p_step_ids)>250 then raise exception 'Select a valid technician list.'using errcode='22023';end if;select coalesce(jsonb_agg(plan),'[]')into result from(select greenloop_private.ps_plan(id)plan from(select distinct unnest(p_step_ids)id)x)y where plan is not null;return result;end;$$;
create or replace function public.save_lab_services_v1(p_step_id uuid,p_services_revision integer,p_services jsonb)returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$declare j uuid;c integer;w uuid;f uuid;r uuid;n text;names jsonb:='[]';s greenloop_private.lab_only_services%rowtype;begin
 perform greenloop_private.pf_cap('lab_glass','entry');j:=greenloop_private.pf_step(p_step_id);c:=greenloop_private.pf_cycle(j);select *into s from greenloop_private.lab_only_services where job_id=j and cycle=c for update;
 if p_services_revision is distinct from coalesce(s.revision,0)then raise exception 'Lab services changed. Refresh before saving.'using errcode='40001';end if;
 if p_services is null or jsonb_typeof(p_services)<>'array'or jsonb_array_length(p_services)>100 then raise exception 'Use a valid Lab services list.'using errcode='22023';end if;
 for n in select value from jsonb_array_elements_text(p_services)loop n:=regexp_replace(btrim(n),'\s+',' ','g');if n is null or length(n)not between 1 and 120 or exists(select 1 from jsonb_array_elements_text(names)x where lower(x)=lower(n))then raise exception 'Use one valid line per service.'using errcode='22023';end if;names:=names||jsonb_build_array(n);end loop;
 perform greenloop_private.pf_context(true);
 select work_order_id into w from public.job_work_order_steps where id=p_step_id;
 update public.lab_service_reviews set is_required=false,reviewed_by=auth.uid(),reviewed_at=now()where work_order_step_id=p_step_id;
 for n in select value from jsonb_array_elements_text(names)loop
 select finding.id into f from public.initial_qc_findings finding join public.job_work_orders wo on wo.initial_qc_inspection_id=finding.inspection_id where wo.id=w and lower(regexp_replace(btrim(finding.check_item),'\s+',' ','g'))=lower(n)order by finding.id limit 1;
 select id into r from public.lab_service_reviews where work_order_step_id=p_step_id and lower(regexp_replace(btrim(service_name),'\s+',' ','g'))=lower(n)order by reviewed_at desc,id limit 1;
 if r is null then insert into public.lab_service_reviews(job_id,work_order_step_id,initial_finding_id,service_name,source,is_required,reviewed_by)values(j,p_step_id,f,n,case when f is null then 'laboratory'else 'initial_qc'end,true,auth.uid());else update public.lab_service_reviews set is_required=true,reviewed_by=auth.uid(),reviewed_at=now()where id=r;end if;
 end loop;
 insert into greenloop_private.lab_only_services(job_id,cycle,step_id,revision,names,saved_by)values(j,c,p_step_id,1,names,auth.uid())on conflict(job_id,cycle)do update set step_id=excluded.step_id,revision=lab_only_services.revision+1,names=excluded.names,saved_at=now(),saved_by=auth.uid(),completed_at=null;
 insert into greenloop_private.lab_only_services_audit(job_id,cycle,action,actor,previous_names,names)values(j,c,'services_saved',auth.uid(),coalesce(s.names,'[]'),names);
 insert into public.device_events(device_id,job_id,event_type,event_title,event_data,actor_id)select device_id,j,'laboratory_services_saved','Lab / Glass saved its service list',jsonb_build_object('service',(select string_agg(value,', ')from jsonb_array_elements_text(names)),'services',names),auth.uid()from public.jobs where id=j;
 perform greenloop_private.pf_context(false);return greenloop_private.ps_plan(p_step_id);
end;$$;
create or replace function public.submit_lab_parts_plan_v2(p_step_id uuid,p_revision integer,p_parts jsonb)returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$begin perform greenloop_private.pf_cap('lab_glass','entry');perform greenloop_private.ps_submit_original(p_step_id,p_revision,p_parts,'[]');return greenloop_private.ps_plan(p_step_id);end;$$;
create or replace function public.complete_parts_only_lab_v1(p_step_id uuid,p_revision integer,p_services_revision integer)returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$declare j uuid;o greenloop_private.parts_flow_orders%rowtype;s jsonb;plan jsonb;result jsonb;begin
 perform greenloop_private.pf_cap('lab_glass','entry');j:=greenloop_private.pf_step(p_step_id);plan:=greenloop_private.ps_plan(p_step_id);s:=greenloop_private.ps_service_state(p_step_id);select *into o from greenloop_private.parts_flow_orders where job_id=j and cycle=greenloop_private.pf_cycle(j)for update;
 if p_revision is distinct from coalesce(o.revision,0)or p_services_revision is distinct from (s->>'services_revision')::integer then raise exception 'The phone changed. Refresh before completing it.'using errcode='40001';end if;
 if not(s->>'services_saved')::boolean and jsonb_array_length(s->'services')>0 then raise exception 'Save the Lab services list before completing the phone.'using errcode='22023';end if;
 if(o.id is null and jsonb_array_length(plan->'parts')>0)or exists(select 1 from jsonb_array_elements(plan->'parts')p where coalesce((p->>'issued')::integer,0)<(p->>'quantity')::integer)or exists(select 1 from jsonb_array_elements(plan->'returns')r where r->>'status'='pending')then raise exception 'Wait for the required parts and return reviews before completing the phone.'using errcode='22023';end if;
 perform greenloop_private.pf_context(true);result:=public.complete_lab_technician_line(p_step_id);
 if o.id is not null then update greenloop_private.parts_flow_orders set completed_at=now(),revision=revision+1 where id=o.id;end if;
 update greenloop_private.lab_only_services set completed_at=now(),revision=revision+1 where job_id=j and cycle=(s->>'cycle')::integer;
 insert into greenloop_private.lab_only_services_audit(job_id,cycle,action,actor,names)values(j,(s->>'cycle')::integer,'lab_completed',auth.uid(),s->'services');perform greenloop_private.pf_context(false);return result;
end;$$;
create or replace function public.get_parts_only_order_v1(p_order_id uuid)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public as $$declare result jsonb;h jsonb;d jsonb;history jsonb:='[]';begin
 perform greenloop_private.pf_cap('parts','view');if not greenloop_private.ps_has_parts(p_order_id)then raise exception 'No parts are requested on this record.'using errcode='22023';end if;
 result:=greenloop_private.ps_order_original(p_order_id);result:=(result-'services')||jsonb_build_object('status',greenloop_private.ps_status(p_order_id));
 for h in select value from jsonb_array_elements(result->'history')loop
 if h->>'action'='service_status'then continue;end if;d:=coalesce(h->'details','{}')-'services';if jsonb_typeof(d->'previous')='object'then d:=jsonb_set(d,'{previous}',(d->'previous')-'services');end if;history:=history||jsonb_build_array(jsonb_set(h,'{details}',d));end loop;
 return jsonb_set(result,'{history}',history);
end;$$;

create or replace function public.get_parts_only_queue_v1(p_filters jsonb default '{}',p_offset integer default 0,p_limit integer default 50,p_sort_key text default 'submitted_at',p_sort_direction text default 'desc')returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public as $$declare f date;t date;s text;st text;result jsonb;begin
 perform greenloop_private.pf_cap('parts','view');
 if jsonb_typeof(p_filters)is distinct from 'object' or exists(select 1 from jsonb_object_keys(p_filters)k where k not in ('_search','_from','_to','status'))or p_offset is null or p_offset<0 or p_limit is null or p_limit not between 1 and 100 or p_sort_key is null or p_sort_key not in ('submitted_at','imei','model','status')or p_sort_direction is null or p_sort_direction not in ('asc','desc')then raise exception 'Select valid filters and sorting.'using errcode='22023';end if;
 if p_filters<>'{}'then perform greenloop_private.pf_cap('parts','search');end if;if p_sort_key<>'submitted_at' or p_sort_direction<>'desc'then perform greenloop_private.pf_cap('parts','sort');end if;
 f:=nullif(p_filters->>'_from','')::date;t:=nullif(p_filters->>'_to','')::date;s:=lower(btrim(coalesce(p_filters->>'_search','')));st:=nullif(p_filters->>'status','');if f>t or length(s)>120 then raise exception 'Select valid dates or search.'using errcode='22023';end if;
 with base as materialized(select o.id order_id,o.revision,o.submitted_at,d.imei_1 imei,d.model,d.storage_gb,d.color,j.job_number,greenloop_private.ps_status(o.id)status,coalesce((select s.assigned_technician_name from public.job_work_order_steps s where s.id=o.step_id),'Unassigned')technician_name,(select count(*)from public.job_part_requests r join greenloop_private.parts_flow_requests m on m.request_id=r.id where m.order_id=o.id and r.status<>'cancelled')parts_count from greenloop_private.parts_flow_orders o join public.jobs j on j.id=o.job_id and j.deleted_at is null join public.devices d on d.id=o.device_id and d.deleted_at is null where greenloop_private.ps_has_parts(o.id)),q as materialized(select * from base where(f is null or(submitted_at at time zone 'Asia/Dubai')::date>=f)and(t is null or(submitted_at at time zone 'Asia/Dubai')::date<=t)and(s=''or strpos(lower(concat_ws(' ',imei,model,storage_gb,color,job_number,technician_name)),s)>0)and(st is null or status=st)),page as(select *from q order by case when p_sort_key='submitted_at'and p_sort_direction='asc'then submitted_at end asc,case when p_sort_key='submitted_at'and p_sort_direction='desc'then submitted_at end desc,case when p_sort_direction='asc'then case p_sort_key when 'imei'then imei when 'model'then model when 'status'then status end end asc,case when p_sort_direction='desc'then case p_sort_key when 'imei'then imei when 'model'then model when 'status'then status end end desc,order_id offset p_offset limit p_limit)
 select jsonb_build_object('legacy_returns',coalesce((select jsonb_agg(jsonb_build_object('id',lr.id,'imei',ld.imei_1,'name',lr.part_name,'quantity',lr.quantity,'reason',lr.return_reason,'at',lr.requested_at)order by lr.requested_at)from public.lab_part_return_requests lr join public.jobs lj on lj.id=lr.job_id and lj.deleted_at is null join public.devices ld on ld.id=lr.device_id and ld.deleted_at is null where lr.status='pending'),'[]'),'total',(select count(*)from q),'rows',coalesce((select jsonb_agg(to_jsonb(p))from page p),'[]'),'facets',jsonb_build_object('status',(select coalesce(jsonb_agg(distinct status),'[]')from base)))into result;return result;
end;$$;

create or replace function public.get_parts_only_counts_v1()returns integer language plpgsql stable security definer set search_path=pg_catalog,public as $$begin perform greenloop_private.require_office_network();if auth.uid()is null or not public.is_active_staff()or greenloop_private.damage_tv_only(auth.uid())then raise exception 'Active staff access required.'using errcode='42501';end if;return(select count(*)::integer from(select o.job_id from greenloop_private.parts_flow_orders o join public.jobs j on j.id=o.job_id and j.deleted_at is null join public.devices d on d.id=o.device_id and d.deleted_at is null where greenloop_private.ps_status(o.id)in ('Sent to Parts','Partially Issued','Return Requested')union select r.job_id from public.lab_part_return_requests r join public.jobs j on j.id=r.job_id and j.deleted_at is null join public.devices d on d.id=r.device_id and d.deleted_at is null where r.status='pending')waiting);end;$$;
-- Old tabs cannot control Lab services through Parts or restore that dependency.
do $redirect$declare n text;impl text;sig text;f record;body text;args text;target text;begin
 foreach n in array array['get_parts_flow_order_v1','get_parts_flow_queue_v1','get_parts_flow_counts_v1','set_parts_flow_service_v1','submit_lab_parts_plan_v1','complete_parts_flow_lab_v1']loop
 select r.implementation into impl from greenloop_private.office_routines r join pg_proc p on p.oid=to_regprocedure(r.identity)where p.proname=n and p.pronamespace='public'::regnamespace;
 if impl is null then raise exception 'Reviewed Parts entry point is missing: %',n;end if;
 select p.* into f from pg_proc p where p.oid=to_regprocedure(impl);
 select coalesce(string_agg('$'||i,','order by i),'')into args from generate_series(1,f.pronargs)i;
 target:=case n when 'get_parts_flow_order_v1'then 'get_parts_only_order_v1'when 'get_parts_flow_queue_v1'then 'get_parts_only_queue_v1'when 'get_parts_flow_counts_v1'then 'get_parts_only_counts_v1'end;
 body:=case when target is not null then 'begin return public.'||target||'('||args||');end;'else 'begin raise exception ''Refresh the page. Services are managed only in Lab / Glass.'' using errcode=''42501'';end;'end;
 execute format('create or replace function greenloop_private.%I(%s)returns %s language plpgsql %s security definer set search_path=pg_catalog,public as %L',f.proname,pg_get_function_arguments(f.oid),pg_get_function_result(f.oid),case f.provolatile when 's'then 'stable'else 'volatile'end,body);
 update greenloop_private.office_routines set original_hash=md5(pg_get_functiondef(to_regprocedure(impl)))where implementation=impl;
 end loop;
end;$redirect$;

insert into greenloop_private.capability_rpc_rules values('get_lab_parts_plans_v2','{"page":"lab_glass","capability":"view","read":true}'::jsonb) on conflict(rpc_name) do update set rule=excluded.rule;
insert into greenloop_private.capability_rpc_rules values('save_lab_services_v1','{"page":"lab_glass","capability":"entry"}'::jsonb) on conflict(rpc_name) do update set rule=excluded.rule;
insert into greenloop_private.capability_rpc_rules values('submit_lab_parts_plan_v2','{"page":"lab_glass","capability":"entry"}'::jsonb) on conflict(rpc_name) do update set rule=excluded.rule;
insert into greenloop_private.capability_rpc_rules values('complete_parts_only_lab_v1','{"page":"lab_glass","capability":"entry"}'::jsonb) on conflict(rpc_name) do update set rule=excluded.rule;
insert into greenloop_private.capability_rpc_rules values('get_parts_only_queue_v1','{"page":"parts","capability":"view","read":true}'::jsonb) on conflict(rpc_name) do update set rule=excluded.rule;
insert into greenloop_private.capability_rpc_rules values('get_parts_only_order_v1','{"page":"parts","capability":"view","read":true}'::jsonb) on conflict(rpc_name) do update set rule=excluded.rule;
insert into greenloop_private.capability_rpc_rules values('get_parts_only_counts_v1','{"any":[{"page":"parts","capability":"view","read":true},{"page":"lab_glass","capability":"view","read":true},{"page":"overview","capability":"view","read":true}]}'::jsonb) on conflict(rpc_name) do update set rule=excluded.rule;
update greenloop_private.page_capability_installation set hash=(select md5(jsonb_agg(to_jsonb(r) order by rpc_name)::text) from greenloop_private.capability_rpc_rules r) where identity='rules';
-- Register the added APIs with the existing office boundary and its audit snapshots.
do $wrap$declare f record;impl text;impl_identity text;args text;body text;begin
 for f in select p.*,pg_get_functiondef(p.oid) ddl,p.oid::regprocedure::text signature from pg_proc p where p.pronamespace='public'::regnamespace and p.proname in ('get_lab_parts_plans_v2','save_lab_services_v1','submit_lab_parts_plan_v2','complete_parts_only_lab_v1','get_parts_only_queue_v1','get_parts_only_order_v1','get_parts_only_counts_v1') loop
  impl:='office_impl_'||f.oid;execute regexp_replace(f.ddl,'FUNCTION public\.'||f.proname||'\(','FUNCTION greenloop_private.'||impl||'(');
  impl_identity:='greenloop_private.'||impl||'('||oidvectortypes(f.proargtypes)||')';execute format('revoke all on function %s from public,anon,authenticated',impl_identity);
  select coalesce(string_agg('$'||i,',' order by i),'') into args from generate_series(1,f.pronargs)i;
  body:=E'begin\n -- greenloop-office-wrapper-196\n perform greenloop_private.require_office_network();\n return greenloop_private.'||impl||'('||args||E');\nend;';
  execute format('create or replace function public.%I(%s) returns %s language plpgsql %s security definer set search_path=pg_catalog,public as %L',f.proname,pg_get_function_arguments(f.oid),pg_get_function_result(f.oid),case f.provolatile when 's' then 'stable' else 'volatile' end,body);
  execute format('revoke all on function %s from public,anon,authenticated',f.signature);execute format('grant execute on function %s to authenticated',f.signature);
  insert into greenloop_private.office_routines values(f.signature,impl_identity,md5(pg_get_functiondef(impl_identity::regprocedure)),md5(pg_get_functiondef(f.oid))) on conflict(identity) do update set implementation=excluded.implementation,original_hash=excluded.original_hash,wrapped_hash=excluded.wrapped_hash;
 end loop;
 for f in select p.oid::regprocedure::text signature from pg_proc p where p.pronamespace='greenloop_private'::regnamespace and p.proname like 'ps_%'loop execute format('revoke all on function %s from public,anon,authenticated',f.signature);end loop;
end;$wrap$;
create table if not exists greenloop_private.parts_services_installation(identity text primary key,hash text not null);
alter table greenloop_private.parts_services_installation enable row level security;
revoke all on greenloop_private.parts_services_installation from public,anon,authenticated;
insert into greenloop_private.parts_services_installation select p.oid::regprocedure::text,md5(pg_get_functiondef(p.oid)) from pg_proc p where (p.pronamespace='public'::regnamespace and p.proname in ('get_lab_parts_plans_v2','save_lab_services_v1','submit_lab_parts_plan_v2','complete_parts_only_lab_v1','get_parts_only_queue_v1','get_parts_only_order_v1','get_parts_only_counts_v1')) or(p.pronamespace='greenloop_private'::regnamespace and p.proname like 'ps_%' or p.oid in(select to_regprocedure(o.implementation)from greenloop_private.office_routines o join pg_proc pub on pub.oid=to_regprocedure(o.identity)where pub.proname in ('get_parts_flow_order_v1','get_parts_flow_queue_v1','get_parts_flow_counts_v1','set_parts_flow_service_v1','submit_lab_parts_plan_v1','complete_parts_flow_lab_v1'))) on conflict(identity) do update set hash=excluded.hash;
create or replace function public.get_parts_services_version() returns text language sql stable security definer set search_path=pg_catalog,public as $$select case when public.get_office_access_version()='20261024-office-access-1' and public.get_parts_flow_version()='20261026-parts-flow-1'
 and (select count(*)=19 and bool_and(hash=md5(pg_get_functiondef(to_regprocedure(identity)))) from greenloop_private.parts_services_installation)
 and not has_table_privilege('authenticated','greenloop_private.parts_services_installation','SELECT,INSERT,UPDATE,DELETE,TRUNCATE')
 and not exists(select 1 from greenloop_private.parts_services_installation where identity like 'greenloop_private.%' and (has_function_privilege('authenticated',to_regprocedure(identity),'EXECUTE') or has_function_privilege('anon',to_regprocedure(identity),'EXECUTE')))
 and not exists(select 1 from unnest(array['parts_services_meta','lab_only_services','lab_only_services_audit'])t where has_table_privilege('authenticated','greenloop_private.'||t,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE')or has_table_privilege('anon','greenloop_private.'||t,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE'))
 then '20261026-parts-services-separate-1' end;$$;
revoke all on function public.get_parts_services_version() from public;grant execute on function public.get_parts_services_version() to anon,authenticated;
do $$begin if public.get_parts_services_version() is distinct from '20261026-parts-services-separate-1' then raise exception 'Parts / Services separation verification failed.';end if;end;$$;
notify pgrst,'reload schema';commit;
select public.get_parts_services_version() as installed_parts_services_version;
